=Atendimento precisa de intervencao humana.
Cliente: {{ $('When Message Received on Telegram').item.json.message.chat.first_name }}
Mensagem: {{ $('When Message Received on Telegram').item.json.message.text }}

parameters.jsCode:
const raw = $input.first().json.output;
let text = (raw === undefined || raw === null) ? '' : String(raw);
let parsed = null;
try {
  const s = text.indexOf('{');
  const e = text.lastIndexOf('}');
  if (s !== -1 && e !== -1 && e > s) { parsed = JSON.parse(text.substring(s, e + 1)); }
} catch (err) { parsed = null; }
if (!parsed || typeof parsed !== 'object') { parsed = { action: 'reply', message_to_client: text || 'Desculpe, nao entendi. Pode repetir, por favor?' }; }
if (parsed.action !== 'book') {
  parsed.action = 'reply';
  if (!parsed.message_to_client || !String(parsed.message_to_client).trim()) { parsed.message_to_client = text || 'Desculpe, nao entendi. Pode repetir, por favor?'; }
}
if (!parsed.booking || typeof parsed.booking !== 'object') { parsed.booking = {}; }
return [{ json: { parsed } }];

